"""Running writer, witness frontier, and automatic device fault contracts."""
# Some portions generated by Codex
import json
from pathlib import Path
import tempfile
import unittest
import socket
import struct
import signal
import sys

from volatile_nbd import Disk, PowerLost, NBD_MAGIC, OPT_MAGIC, REQ_MAGIC, recvn
from runner_common import backend_control, start_backend, stop_process


class AutomaticFaultTests(unittest.TestCase):
    def setUp(self):
        self.temporary = tempfile.TemporaryDirectory()
        self.image = Path(self.temporary.name) / "data.raw"
        with self.image.open("wb") as stream:
            stream.truncate(1024 * 1024)
        self.disk = Disk(self.image)

    def tearDown(self):
        self.disk.close()
        self.temporary.cleanup()

    def test_automatic_write_cut_interrupts_an_interior_sector_without_ack(self):
        schedule = self.disk.arm("write", seed=41, request_window=1)
        with self.assertRaises(PowerLost):
            self.disk.write(0, b"X" * 4096)
        cut = self.disk.status()["automatic_cut"]
        self.assertEqual(cut["schedule"], schedule)
        self.assertGreater(cut["request"]["sectors_completed"], 0)
        self.assertLess(cut["request"]["sectors_completed"], 8)
        self.assertFalse(cut["request"]["successful_reply"])
        self.assertEqual(self.image.read_bytes()[:4096], bytes(4096))
        self.assertEqual(self.disk.counts["cuts"], 1)

    def test_automatic_flush_preserves_only_its_interior_persisted_prefix(self):
        self.disk.write(0, b"A" * 4096)
        self.disk.arm("persistence", seed=17, request_window=1)
        with self.assertRaises(PowerLost):
            self.disk.flush()
        request = self.disk.status()["automatic_cut"]["request"]
        completed = request["sectors_completed"]
        self.assertGreater(completed, 0)
        self.assertLess(completed, 8)
        self.assertEqual(self.disk.counts["completed_flushes"], 0)
        self.assertEqual(self.image.read_bytes()[:4096], b"A" * (512 * completed) + bytes(512 * (8 - completed)))

    def test_schedule_is_seeded_single_shot_and_counts_only_future_eligible_io(self):
        self.disk.write(0, b"A" * 4096, fua=True)
        schedule = self.disk.arm("write", seed=5, request_window=3)
        self.disk.write(4096, b"B" * 512)
        for ordinal in range(1, schedule["request_ordinal"] + 1):
            if ordinal == schedule["request_ordinal"]:
                with self.assertRaises(PowerLost):
                    self.disk.write(8192, b"C" * 4096)
            else:
                self.disk.write(8192, b"C" * 4096)
        self.assertEqual(self.image.read_bytes()[:4096], b"A" * 4096)
        with self.assertRaises((ValueError, PowerLost)):
            self.disk.arm("write", seed=5, request_window=3)
        self.assertEqual(self.disk.counts["cuts"], 1)

    def test_invalid_faults_are_rejected_and_unarmed_flush_fua_stay_durable(self):
        for kind, window in (("read", 1), ("write", 0), ("persistence", -1)):
            with self.assertRaises(ValueError):
                self.disk.arm(kind, seed=1, request_window=window)
        self.disk.write(0, b"A" * 4096)
        self.disk.flush()
        self.disk.write(4096, b"B" * 4096, fua=True)
        self.disk.cut()
        self.assertEqual(self.image.read_bytes()[:8192], b"A" * 4096 + b"B" * 4096)

    def test_interior_fua_does_not_rescue_unrelated_volatile_data(self):
        self.disk.write(0, b"A" * 4096)
        self.disk.arm("persistence", seed=17, request_window=1)
        with self.assertRaises(PowerLost):
            self.disk.write(4096, b"B" * 4096, fua=True)
        request = self.disk.status()["automatic_cut"]["request"]
        self.assertEqual(request["kind"], "FUA")
        self.assertEqual(self.image.read_bytes()[:4096], bytes(4096))
        self.assertEqual(self.image.read_bytes()[4096:8192],
                         b"B" * (512 * request["sectors_completed"]) + bytes(512 * (8 - request["sectors_completed"])))


class RunningWitnessTests(unittest.TestCase):
    def test_final_witnesses_ignore_temporary_markers_but_reject_torn_hash_gap_and_foreign_finals(self):
        import hashlib
        from running_contract import read_running_witnesses
        trial = "running-normal-preflight-write"
        with tempfile.TemporaryDirectory() as temporary:
            root = Path(temporary)
            for generation in range(1, 4):
                payload = f"# RDF4J-RUNNING-PAYLOAD-V1\t{trial}\t{generation}\n# exact payload\n"
                (root / f"running-{generation}-attempt.tsv").write_text(payload)
                if generation < 3:
                    (root / f"running-{generation}-returned.json").write_text(json.dumps({
                        "trial": trial, "generation": generation, "commit_returned": True,
                        "payload_sha256": hashlib.sha256(payload.encode()).hexdigest()}))
            (root / "running-3-returned.json.tmp").write_text('{"unfinished":')
            bounds = read_running_witnesses(root, trial)
            self.assertEqual((bounds["returned_generation"], bounds["attempted_generation"]), (2, 3))
            target = root / "running-2-returned.json"
            original = target.read_text()
            for invalid in ('{"unfinished":', original.replace(trial, "foreign-trial"),
                            original.replace(json.loads(original)["payload_sha256"], "0" * 64)):
                target.write_text(invalid)
                with self.assertRaises(ValueError):read_running_witnesses(root, trial)
            target.write_text(original)
            (root / "running-5-attempt.tsv").write_text(f"# RDF4J-RUNNING-PAYLOAD-V1\t{trial}\t5\n# payload\n")
            with self.assertRaises(ValueError):read_running_witnesses(root, trial)

    def test_complete_optional_frontier_is_allowed_but_acknowledged_loss_is_rejected(self):
        from running_contract import validate_running_recovery_pair
        bounds = {"returned_generation": 2, "attempted_generation": 3}
        for generation in (2, 3):
            result = {"generation": generation, "stateSha256": "a" * 64}
            validate_running_recovery_pair(bounds, result, result)
        with self.assertRaises(ValueError):
            validate_running_recovery_pair(bounds, {"generation": 1, "stateSha256": "a" * 64},
                                           {"generation": 1, "stateSha256": "a" * 64})

    def test_nonsequential_frontiers_and_different_recoveries_are_rejected(self):
        from running_contract import validate_running_recovery_pair
        for bounds in ({"returned_generation": 3, "attempted_generation": 2},
                       {"returned_generation": 2, "attempted_generation": 4}):
            with self.assertRaises(ValueError):
                validate_running_recovery_pair(bounds, {"generation": 3, "stateSha256": "a" * 64},
                                               {"generation": 3, "stateSha256": "a" * 64})
        with self.assertRaises(ValueError):
            validate_running_recovery_pair({"returned_generation": 2, "attempted_generation": 3},
                                           {"generation": 2, "stateSha256": "a" * 64},
                                           {"generation": 3, "stateSha256": "a" * 64})


class AutomaticControlTests(unittest.TestCase):
    def test_real_backend_control_arms_after_ready_and_captures_activity_at_fault(self):
        trial = "running-normal-preflight-write"
        with tempfile.TemporaryDirectory(dir="/tmp") as temporary:
            root = Path(temporary)
            image = root / "data.raw"
            image.write_bytes(bytes(8192))
            control = root / "control.sock"
            backend_source = Path(__file__).with_name("volatile_nbd.py")
            ready = {"trial": trial, "profile": "normal-preflight", "returned_generation": 2,
                     "writer_pid": 123, "force_sync": True, "generation_controller_releases": 0, "spilled_replays": 0,
                     "spilled_replay_observation": "before_replay_hook"}
            (root / "actual-running-ready.json").write_text(json.dumps(ready))
            activity = {"trial": trial, "last_published_generation": 2, "last_published_returned_generation": 1,
                        "writer_pid": 123, "last_published_phase": "before_transaction"}
            (root / "actual-running-activity.json").write_text(json.dumps(activity))
            with socket.socket() as reserved:
                reserved.bind(("127.0.0.1", 0))
                port = reserved.getsockname()[1]
            backend = start_backend(python=Path(sys.executable), backend=backend_source, image=image,
                                    control=control, port=port, events=root / "events.jsonl",
                                    log=root / "backend.log", command_record=root / "command.json")
            try:
                schedule = backend_control(Path(sys.executable), backend_source, control, "arm",
                                           "--fault-kind", "write", "--seed", "41", "--request-window", "1",
                                           "--activity-dir", str(root), "--trial", trial)
                activity.update(last_published_generation=3, last_published_returned_generation=2)
                (root / "actual-running-activity.json").write_text(json.dumps(activity))
                with socket.create_connection(("127.0.0.1", port), timeout=5) as client:
                    self.assertEqual(struct.unpack(">QQH", recvn(client, 18)), (NBD_MAGIC, OPT_MAGIC, 3))
                    client.sendall(struct.pack(">I", 3))
                    client.sendall(struct.pack(">QII", OPT_MAGIC, 1, 8) + b"crashlab")
                    recvn(client, 10)
                    client.sendall(struct.pack(">IHHQQI", REQ_MAGIC, 0, 1, 1, 0, 4096) + b"X" * 4096)
                    with self.assertRaises(EOFError):recvn(client, 16)
                status = backend_control(Path(sys.executable), backend_source, control, "status")
                cut = status["automatic_cut"]
                self.assertTrue(status["off"])
                self.assertEqual(cut["activity"], activity)
                self.assertEqual(cut["schedule"], schedule)
                self.assertEqual(cut["actual_cut_time_ns"], cut["fenced_time_ns"])
            finally:
                stop_process(backend, signal.SIGINT)


if __name__ == "__main__":
    unittest.main(verbosity=2)
